import{_ as a,o as l,c as e,ab as i}from"./chunks/framework.DQy4ijAa.js";const p=JSON.parse('{"title":"概念","description":"","frontmatter":{},"headers":[],"relativePath":"ai/langChain/agents.md","filePath":"ai/langChain/agents.md","lastUpdated":1773975001000}'),n={name:"ai/langChain/agents.md"};function o(d,t,r,s,c,h){return l(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h1><p>Agent（智能体） 是一个通过动态协调 大语言模型（LLM） 和 工具（Tools） 来完成复杂任务的智能系 统。它让LLM充当&quot;决策大脑&quot;，根据用户输入自主选择和执行工具（如搜索、计算、数据库查询等）， 最终生成精准的响应。</p><h2 id="agent的核心能力-组件" tabindex="-1">Agent的核心能力/组件 <a class="header-anchor" href="#agent的核心能力-组件" aria-label="Permalink to &quot;Agent的核心能力/组件&quot;">​</a></h2><ol><li><p>大模型(LLM)：作为大脑，提供推理、规划和知识理解能力。</p><ul><li>比如：OpenaAI()、ChatOpenAI()</li></ul></li><li><p>记忆(Memory)：具备短期记忆（上下文）和长期记忆（向量存储），支持快速知识检索。</p></li><li><p>工具(Tools)：调用外部工具（如API、数据库）的执行单元</p><ul><li>比如：SearchTool、CalculatorTool</li><li>必要性：大模型虽然非常强大，但是也具备一定的局限性。比如不能回答 <code>实时信息</code> 、处理 <code>复杂数学逻辑</code> 问题</li><li>在LangChain框架内，每个功能或函数被 <code>封装成一个工具 （Tools）</code>，具有自己的输入、输出及处理方法。 等等。因此，可以借助第三方工具来辅助大模型的应用。</li></ul></li><li><p>规划(Planning)：任务分解、反思与自省框架实现复杂任务处理</p></li><li><p>行动(Action)：实际执行决策的能力 比如：检索、推理、编程</p></li><li><p>协作：通过与其他智能体交互合作，完成更复杂的任务目标</p></li></ol><h2 id="agents的核心类型有两种模式" tabindex="-1">Agents的核心类型有两种模式 <a class="header-anchor" href="#agents的核心类型有两种模式" aria-label="Permalink to &quot;Agents的核心类型有两种模式&quot;">​</a></h2><h3 id="funcation-call模式" tabindex="-1">FUNCATION_CALL模式 <a class="header-anchor" href="#funcation-call模式" aria-label="Permalink to &quot;FUNCATION_CALL模式&quot;">​</a></h3><ol><li>基于 <strong>结构化函数调用</strong> （如 OpenAI Function Calling）</li><li>直接生成工具调用参数（ JSON 格式 ）</li><li>效率更高，适合工具明确的场景</li></ol><h3 id="react-模式" tabindex="-1">ReAct 模式 <a class="header-anchor" href="#react-模式" aria-label="Permalink to &quot;ReAct 模式&quot;">​</a></h3><ol><li>基于 <strong>文本推理</strong> 的链式思考（Reasoning + Acting），具备反思和自我纠错能力。 <ul><li>推理（Reasoning）：分析当前状态，决定下一步行动</li><li>行动（Acting）：调用工具并返回结果</li></ul></li><li>通过 <strong>自然语言</strong>描述决策过程</li><li>适合需要明确推理步骤的场景。例如智能客服、问答系统、任务执行等</li></ol><table tabindex="0"><thead><tr><th>特性</th><th>Function Call模式</th><th>ReAct 模式</th></tr></thead><tbody><tr><td>底层机制</td><td>结构化函数调用</td><td>自然语言推理</td></tr><tr><td>输出格式</td><td>JSON/结构化数据</td><td>自由文本</td></tr><tr><td>适合场景</td><td>需要高效工具调用</td><td>需要解释决策过程</td></tr><tr><td>典型延迟</td><td>较低 （直接参数化调用） 较高</td><td>（需生成完整文本）</td></tr><tr><td>LLM要求</td><td>需支持函数调用（如gpt-4）</td><td>通用模型即可</td></tr></tbody></table><h1 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to &quot;使用&quot;">​</a></h1>',11)])])}const u=a(n,[["render",o]]);export{p as __pageData,u as default};
